TRAIN_PREFIXES = ["", "Подскажите, пожалуйста: ", "Нужен совет приёмщика. ", "Хочу записаться в сервис: ", "Помогите разобраться: "]
EVAL_PREFIXES = ["", "Объясните простыми словами: "]


def urgency_note(level):
    return {"остановиться": "Есть признаки опасной неисправности.", "скоро": "Нужна диагностика в ближайшее время.", "планово": "Подходит плановое обслуживание по регламенту."}[level]


def build():
    data = ROOT / "data"
    splits = {}
    for split, scenarios, prefixes in [("train", TRAIN, TRAIN_PREFIXES), ("dev", DEV, EVAL_PREFIXES)]:
        rows = []
        for group, topic, level, q, causes, action, clarifications in scenarios:
            action = (action + " При обращении в сервис сообщите модель, пробег и историю обслуживания; "
                      "конкретный перечень работ согласуют только после проверки автомобиля.")
            response = (f"Срочность: {level}. {urgency_note(level)}\n"
                        f"Возможные причины: {causes}\nЧто сделать: {action}\nУточните: {clarifications}")
            for i, prefix in enumerate(prefixes):
                question = prefix + q
                rows.append({"id": f"{group}_{i}", "group": group, "topic": topic,
                             "expected_urgency": level, "source": "synthetic_assistant_draft_v1",
                             "messages": [{"role": "system", "content": SYSTEM},
                                          {"role": "user", "content": question},
                                          {"role": "assistant", "content": response}]})
        splits[split] = rows
    splits["test"] = [{"id": f"{g}_{i}", "group": g, "topic": t, "expected_urgency": u,
                       "question": prefix + q, "rubric": r, "source": "synthetic_assistant_draft_v1"}
                      for g, t, u, q, r in TEST for i, prefix in enumerate(EVAL_PREFIXES)]
    groups = {s: {r["group"] for r in rows} for s, rows in splits.items()}
    assert not (groups["train"] & groups["dev"] or groups["train"] & groups["test"] or groups["dev"] & groups["test"])
    all_questions = [r.get("question", r.get("messages", [{}, {}])[1].get("content")) for rows in splits.values() for r in rows]
    assert len(all_questions) == len(set(all_questions))
    manifest = {"provenance": "Синтетические примеры созданы ассистентом при подготовке работы; экспертная разметка отсутствует.",
                "split_method": "Фиксированный split по семейству сценария; варианты не пересекают границы split.",
                "limitations": "Пять train-вариантов различаются только вводной фразой и имеют одинаковый ответ. Это контролируемая адаптация формата, не большой корпус технических знаний.",
                "splits": {}}
    for split, rows in splits.items():
        path = data / f"{split}.jsonl"
        write_jsonl(path, rows)
        manifest["splits"][split] = {"rows": len(rows), "groups": len(groups[split]),
                                    "urgency": dict(Counter(r["expected_urgency"] for r in rows)),
                                    "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
    write_json(data / "manifest.json", manifest)
    print(manifest)


if __name__ == "__main__":
    build()
